import json
import subprocess
from pathlib import Path

wt = Path("/Users/steventran/.do_again/selfdev-20261007")
expected = "585fbf9340de57a9bc6fcd662e5979bb37a9c7c9"

def run(args, cwd=wt):
    return subprocess.run(args, cwd=cwd, text=True, capture_output=True, check=True).stdout

head = run(["git","rev-parse","HEAD"]).strip()
status = run(["git","status","--porcelain=v1"]).strip()
if head != expected or status:
    raise SystemExit(f"unexpected isolated state head={head} status={status!r}")

p = wt/"src/do_again/browser/runtime.py"
lines=p.read_text().splitlines()
for start,end in [(975,1035),(1035,1140),(1140,1245)]:
    print(f"=== runtime {start}-{end} ===")
    for n in range(start,min(end,len(lines))+1):
        print(f"{n:04d}: {lines[n-1]}")

print("=== project records ===")
home=Path.home()/".do_again"
for p in sorted((home/"browser"/"projects").glob("*.json")) if (home/"browser"/"projects").exists() else []:
    try: data=json.loads(p.read_text())
    except Exception as exc:
        print(p, "ERROR", exc); continue
    safe={k:data.get(k) for k in (
        "key","repo","chat_url","previous_chat_url","rollover_count","last_rollover_utc",
        "active","daemon_pid","remote_url","control_branch"
    )}
    print(json.dumps({"path":str(p),**safe}, sort_keys=True))

candidates=[
"6ac69a7a-6fe8-83e8-b3f4-6f0c333df723",
"6ac69ad4-6524-83e8-827f-d1f93b18f5dd",
"6ac69ba8-fe28-83e8-aee5-87a87a77258a",
"6ac69bd2-b3d0-83e8-9747-9cc5ed3516ef",
]
print("=== candidate references under ~/.do_again text/json/log files ===")
for cid in candidates:
    print("--",cid)
    proc=subprocess.run(
        ["grep","-RIl",cid,str(home)],
        text=True,capture_output=True
    )
    paths=[x for x in proc.stdout.splitlines() if x]
    for path in paths[:50]:
        print(path)
    if not paths: print("(none)")
